import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"PLC industrial — Donde el software toca el acero","description":"Programación PLC en Ladder y Texto Estructurado (IEC 61131-3), diseño HMI, lógica SCADA — automatización en líneas de producción reales.","frontmatter":{"title":"PLC industrial — Donde el software toca el acero","description":"Programación PLC en Ladder y Texto Estructurado (IEC 61131-3), diseño HMI, lógica SCADA — automatización en líneas de producción reales."},"headers":[],"relativePath":"es/skills/plc/index.md","filePath":"es/skills/plc/index.md"}`),a={name:`es/skills/plc/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="plc-industrial-—-donde-el-software-toca-el-acero" tabindex="-1">PLC industrial — Donde el software toca el acero <a class="header-anchor" href="#plc-industrial-—-donde-el-software-toca-el-acero" aria-label="Permalink to “PLC industrial — Donde el software toca el acero”">​</a></h1><p>Antes de las APIs web estaban los cables. La automatización industrial me enseñó que el software tiene consecuencias que se pueden oír — una mala línea de lógica no lanza una excepción, detiene una línea de producción o pellizca un dedo. Programo PLCs en <strong>Ladder Diagram</strong> y <strong>Texto Estructurado</strong> bajo IEC 61131-3, y diseño los HMIs que los operadores realmente usan.</p><h2 id="lo-que-hago-en-la-planta" tabindex="-1">Lo que hago en la planta <a class="header-anchor" href="#lo-que-hago-en-la-planta" aria-label="Permalink to “Lo que hago en la planta”">​</a></h2><table tabindex="0"><thead><tr><th>Área</th><th>Práctica</th></tr></thead><tbody><tr><td>Lógica</td><td>Ladder (LD) para control discreto; Texto Estructurado (ST) para matemática y secuencias.</td></tr><tr><td>HMI</td><td>Pantallas que los operadores leen de un vistazo, en su idioma, con alarmas honestas.</td></tr><tr><td>Pensamiento SCADA</td><td>Nomenclatura de tags, racionalización de alarmas, registro de datos que sobrevive auditorías.</td></tr><tr><td>Seguridad</td><td>Interlocks primero, conveniencia después — siempre.</td></tr></tbody></table><p>La automatización me hizo mejor ingeniero de software de tres formas específicas: respeto las <strong>máquinas de estados</strong> (una línea de producción es una máquina de estados gigante), escribo <strong>código defensivo</strong> (los sensores mienten, los contactos se sueldan), y documento como si el próximo lector estuviera parado junto a una máquina encendida — porque a veces lo está.</p><blockquote><p>En control industrial, el uptime se mide en toneladas, no en nueves.</p></blockquote>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};